import{_ as e,C as i,c as n,o as a,a0 as t,b as r,w as l,a as s,G as o,a1 as h}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Teamkommunikation","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/team-player/communication.md","filePath":"de/education/team-player/communication.md"}');const d=e({name:"de/education/team-player/communication.md"},[["render",function(e,u,d,m,c,g){const k=i("Mermaid");return a(),n("div",null,[u[1]||(u[1]=t('<h1 id="teamkommunikation" tabindex="-1">Teamkommunikation <a class="header-anchor" href="#teamkommunikation" aria-label="Permalink to &quot;Teamkommunikation&quot;">​</a></h1><p>Effektive Kommunikation ist das, was aus einer Gruppe von Einzelpersonen ein Team macht. Beim Boule, wo sich die Strategie ständig ändert und der Druck hoch ist, kann die Art der Kommunikation über den Ausgang entscheiden.</p><div class="tip custom-block"><p class="custom-block-title">Die große Idee</p><p><strong>Kommunikation ist das, was aus Einzelpersonen ein Team macht.</strong> Klare, präzise und unterstützende Kommunikation unter Druck unterscheidet gute Teams von großartigen.</p></div><h2 id="der-kommunikationszyklus" tabindex="-1">Der Kommunikationszyklus <a class="header-anchor" href="#der-kommunikationszyklus" aria-label="Permalink to &quot;Der Kommunikationszyklus&quot;">​</a></h2><p>Gute Teamkommunikation folgt einem Zyklus:</p>',5)),(a(),r(h,null,{default:l(()=>[o(k,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BBeobachten%5D%20--%3E%20B%5BAktie%5D%0A%20%20%20%20B%20--%3E%20C%5BDiskutieren%5D%0A%20%20%20%20C%20--%3E%20D%5BEntscheiden%5D%0A%20%20%20%20D%20--%3E%20E%5BAusf%C3%BChren%5D%0A%20%20%20%20E%20--%3E%20F%5BRezension%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:l(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=t('<table tabindex="0"><thead><tr><th>Schritt</th><th>Aktion</th><th>Beispiel</th></tr></thead><tbody><tr><td><strong>Beobachten</strong></td><td>Beobachten Sie, was passiert.</td><td>Gelände, Stellungen, Gegner</td></tr><tr><td><strong>Aktie</strong></td><td>Teile deinen Teamkollegen mit, was du siehst.</td><td>„Das Gelände fällt dort ab.“</td></tr><tr><td><strong>Diskutieren</strong></td><td>Perspektiven austauschen</td><td>Soll ich blocken oder auf Punkt gehen?</td></tr><tr><td><strong>Entscheiden</strong></td><td>Einigung über das Vorgehen</td><td>&quot;Versuchen wir es mal mit einem hohen Lob.&quot;</td></tr><tr><td><strong>Ausführen</strong></td><td>Tu es mit Engagement</td><td>Volle Konzentration auf den Wurf</td></tr><tr><td><strong>Rezension</strong></td><td>Aus den Ergebnissen lernen</td><td>&quot;Das hat gut funktioniert&quot; oder &quot;Nächstes Mal...&quot;</td></tr></tbody></table><h2 id="wann-kommunizieren" tabindex="-1">Wann kommunizieren? <a class="header-anchor" href="#wann-kommunizieren" aria-label="Permalink to &quot;Wann kommunizieren?&quot;">​</a></h2><h3 id="vor-jedem-ende" tabindex="-1">Vor jedem Ende <a class="header-anchor" href="#vor-jedem-ende" aria-label="Permalink to &quot;Vor jedem Ende&quot;">​</a></h3><ul><li>Das Gelände gemeinsam beurteilen</li><li>Allgemeine Vorgehensweise erörtern</li><li>Klären Sie, wer wann wirft.</li><li>Die richtige Atmosphäre schaffen (ruhig, konzentriert).</li></ul><h3 id="wahrend-des-endes" tabindex="-1">Während des Endes <a class="header-anchor" href="#wahrend-des-endes" aria-label="Permalink to &quot;Während des Endes&quot;">​</a></h3><ul><li>Beobachtungen teilen (Die dortigen Hanglagen)</li><li>Strategie koordinieren („Soll ich versuchen zu blocken oder den Punkt zu erzielen?“)</li><li>Biete Unterstützung an („Lass dir Zeit, du schaffst das“)</li><li>Passen Sie Ihre Pläne an die sich ändernde Situation an.</li></ul><h3 id="zwischen-den-enden" tabindex="-1">Zwischen den Enden <a class="header-anchor" href="#zwischen-den-enden" aria-label="Permalink to &quot;Zwischen den Enden&quot;">​</a></h3><ul><li>Kurzes Debriefing (was funktioniert hat, was nicht)</li><li>Mental neu ausrichten</li><li>Bereiten Sie sich auf das nächste Ende vor</li><li>Bleibt als Team in Verbindung.</li></ul><h3 id="nach-dem-spiel" tabindex="-1">Nach dem Spiel <a class="header-anchor" href="#nach-dem-spiel" aria-label="Permalink to &quot;Nach dem Spiel&quot;">​</a></h3><ul><li>Vollständige Nachbesprechung (falls angebracht)</li><li>Beiträge anerkennen</li><li>Erkenntnisse identifizieren</li><li>Beziehung pflegen</li></ul><h2 id="wie-man-kommuniziert" tabindex="-1">Wie man kommuniziert <a class="header-anchor" href="#wie-man-kommuniziert" aria-label="Permalink to &quot;Wie man kommuniziert&quot;">​</a></h2><h3 id="seien-sie-klar-und-prazise" tabindex="-1">Seien Sie klar und präzise. <a class="header-anchor" href="#seien-sie-klar-und-prazise" aria-label="Permalink to &quot;Seien Sie klar und präzise.&quot;">​</a></h3><p><strong>Vage:</strong> &quot;Versuche, näher heranzukommen&quot; <strong>Hinweis:</strong> „Zielen Sie auf die linke Seite des Wagenhebers, etwa 20 cm entfernt.“</p><p><strong>Vage:</strong> „Netter Versuch“ <strong>Klar:</strong> „Gutes Gewicht, nur ein bisschen links von der Linie“</p><h3 id="sei-konstruktiv" tabindex="-1">Sei konstruktiv <a class="header-anchor" href="#sei-konstruktiv" aria-label="Permalink to &quot;Sei konstruktiv&quot;">​</a></h3><p>Konzentriere dich auf Lösungen, nicht auf Probleme:</p><p><strong>Problemorientiert:</strong> „Du verfehlst immer wieder das Ziel nach rechts.“ <strong>Lösungsorientiert:</strong> „Vielleicht versuchen Sie, etwas weiter links zu zielen, um das auszugleichen?“</p><h3 id="sei-unterstutzend" tabindex="-1">Sei unterstützend <a class="header-anchor" href="#sei-unterstutzend" aria-label="Permalink to &quot;Sei unterstützend&quot;">​</a></h3><p>Ihr Tonfall ist genauso wichtig wie Ihre Worte:</p><ul><li>Bleiben Sie ruhig, auch wenn Sie frustriert sind.</li><li>Setzen Sie eine ermutigende Körpersprache ein.</li><li>Würdigen Sie den Einsatz, nicht nur die Ergebnisse.</li><li>Aufbauen, nicht abreißen</li></ul><h3 id="aktiv-zuhoren" tabindex="-1">Aktiv zuhören <a class="header-anchor" href="#aktiv-zuhoren" aria-label="Permalink to &quot;Aktiv zuhören&quot;">​</a></h3><p>Die Kommunikation ist wechselseitig:</p><ul><li>Schenke deinen Teamkollegen deine volle Aufmerksamkeit, wenn sie sprechen.</li><li>Stellen Sie klärende Fragen</li><li>Bestätige, was du gehört hast</li><li>Unterbrechen oder abweisen Sie nicht</li></ul><h2 id="kommunikationsherausforderungen" tabindex="-1">Kommunikationsherausforderungen <a class="header-anchor" href="#kommunikationsherausforderungen" aria-label="Permalink to &quot;Kommunikationsherausforderungen&quot;">​</a></h2><h3 id="uneinigkeit-uber-die-strategie" tabindex="-1">Uneinigkeit über die Strategie <a class="header-anchor" href="#uneinigkeit-uber-die-strategie" aria-label="Permalink to &quot;Uneinigkeit über die Strategie&quot;">​</a></h3><p><strong>Schlechte Herangehensweise:</strong></p><ul><li>Beharre auf deinem Weg</li><li>In die Defensive gehen</li><li>widerwillig nachgeben</li><li>Streitet euch während des Spiels</li></ul><p><strong>Besserer Ansatz:</strong></p><ol><li>Teilen Sie Ihre Sichtweise klar mit.</li><li>Hören Sie sich ihre vollständige Version an.</li><li>Besprechen Sie kurz die Vor- und Nachteile.</li><li>Gemeinsam entscheiden (oder dem designierten Leiter die Entscheidung überlassen)</li><li>Stehe voll und ganz zu dieser Entscheidung.</li><li>Rückblick nach dem Spiel</li></ol><h3 id="nach-einem-fehler-eines-teamkollegen" tabindex="-1">Nach einem Fehler eines Teamkollegen <a class="header-anchor" href="#nach-einem-fehler-eines-teamkollegen" aria-label="Permalink to &quot;Nach einem Fehler eines Teamkollegen&quot;">​</a></h3><p><strong>Was sie benötigen:</strong></p><ul><li>Kurze Bestätigung</li><li>Erlaubnis zum Weitergehen</li><li>Das Vertrauen, dass du ihnen immer noch vertraust.</li><li>Konzentriere dich auf den nächsten Wurf.</li></ul><p><strong>Was Sie sagen sollten:</strong></p><ul><li>&quot;Kein Problem, der nächste.&quot;</li><li>„Pech gehabt, aber du bist dran.“</li><li>&quot;Wir stecken immer noch mittendrin.&quot;</li><li>Manchmal genügt schon ein Nicken oder ein Klaps.</li></ul><p><strong>Was Sie NICHT sagen sollten:</strong></p><ul><li>Nichts (Schweigen fühlt sich wie ein Urteil an)</li><li>„Schon gut“ (kann abweisend klingen)</li><li>Alles darüber, was schiefgelaufen ist (nicht jetzt).</li><li>Sichtbare Frustration (Körpersprache zählt)</li></ul><h3 id="wenn-sie-einen-fehler-machen" tabindex="-1">Wenn Sie einen Fehler machen <a class="header-anchor" href="#wenn-sie-einen-fehler-machen" aria-label="Permalink to &quot;Wenn Sie einen Fehler machen&quot;">​</a></h3><p><strong>Was zu tun:</strong></p><ul><li>Kurze Bestätigung („Mein Fehler“)</li><li>Übermäßiges Entschuldigen</li><li>Mach keine Ausreden.</li><li>Neu ausrichten und sich auf den nächsten Wurf konzentrieren.</li><li>Vertraue darauf, dass deine Teamkollegen dich unterstützen.</li></ul><h3 id="spannungen-im-team" tabindex="-1">Spannungen im Team <a class="header-anchor" href="#spannungen-im-team" aria-label="Permalink to &quot;Spannungen im Team&quot;">​</a></h3><p>Wenn sich während eines Spiels Spannungen aufbauen:</p><ol><li>Erkenne, dass es passiert.</li><li>Atmen Sie tief durch, bevor Sie antworten.</li><li>Konzentriere dich auf das Spiel, nicht auf den Konflikt.</li><li>Klären Sie das Problem nach dem Spiel angemessen ab.</li><li>Lass dich davon nicht in deinem Spiel beeinflussen.</li></ol><h2 id="nonverbale-kommunikation" tabindex="-1">Nonverbale Kommunikation <a class="header-anchor" href="#nonverbale-kommunikation" aria-label="Permalink to &quot;Nonverbale Kommunikation&quot;">​</a></h2><p>Ein Großteil der Teamkommunikation ist nonverbal:</p><h3 id="positive-signale" tabindex="-1">Positive Signale <a class="header-anchor" href="#positive-signale" aria-label="Permalink to &quot;Positive Signale&quot;">​</a></h3><ul><li>Blickkontakt</li><li>Nicken</li><li>Daumen hoch</li><li>Entspannte Haltung</li><li>Auf die Teamkollegen zugehen</li><li>Lächeln (wenn angebracht)</li></ul><h3 id="negative-signale-diese-vermeiden" tabindex="-1">Negative Signale (Diese vermeiden) <a class="header-anchor" href="#negative-signale-diese-vermeiden" aria-label="Permalink to &quot;Negative Signale (Diese vermeiden)&quot;">​</a></h3><ul><li>Augenrollen</li><li>Abkehr</li><li>Verkreuzte Arme</li><li>Seufzen</li><li>Kopfschütteln</li><li>Angespannte Körpersprache</li></ul><p><strong>Denk daran:</strong> Deine Teamkollegen sehen alles. Deine Körpersprache beeinflusst ihr Selbstvertrauen und ihre Leistung.</p><h2 id="aufbau-von-kommunikationsgewohnheiten" tabindex="-1">Aufbau von Kommunikationsgewohnheiten <a class="header-anchor" href="#aufbau-von-kommunikationsgewohnheiten" aria-label="Permalink to &quot;Aufbau von Kommunikationsgewohnheiten&quot;">​</a></h2><h3 id="kommunikation-uben" tabindex="-1">Kommunikation üben <a class="header-anchor" href="#kommunikation-uben" aria-label="Permalink to &quot;Kommunikation üben&quot;">​</a></h3><p>Warten Sie nicht darauf, dass die Konkurrenz kommuniziert:</p><ul><li>Üben Sie strategische Diskussionen im Training</li><li>Geben Sie sich regelmäßig gegenseitig Feedback.</li><li>Entwickeln Sie Ihre Teamsprache</li><li>Schaffen Sie Vertrauen durch ehrliche Gespräche</li></ul><h3 id="teamsignale-entwickeln" tabindex="-1">Teamsignale entwickeln <a class="header-anchor" href="#teamsignale-entwickeln" aria-label="Permalink to &quot;Teamsignale entwickeln&quot;">​</a></h3><p>Manche Teams entwickeln Kurzformen:</p><ul><li>Handzeichen zur Strategie</li><li>Codewörter für Situationen</li><li>Kurze Sätze mit gemeinsamer Bedeutung</li></ul><h3 id="regelmaßige-check-ins" tabindex="-1">Regelmäßige Check-ins <a class="header-anchor" href="#regelmaßige-check-ins" aria-label="Permalink to &quot;Regelmäßige Check-ins&quot;">​</a></h3><p>Außerhalb von Spielen:</p><ul><li>Wie gestalten wir unsere Zusammenarbeit?</li><li>Was läuft gut?</li><li>Was könnte besser sein?</li><li>Gibt es Probleme, die angegangen werden müssen?</li></ul><h2 id="die-rolle-des-kapitans" tabindex="-1">Die Rolle des Kapitäns <a class="header-anchor" href="#die-rolle-des-kapitans" aria-label="Permalink to &quot;Die Rolle des Kapitäns&quot;">​</a></h2><p>Wenn Ihr Team einen designierten Leiter hat:</p><p><strong>Aufgaben des Kapitäns:</strong></p><ul><li>Endgültige Entscheidung bei Uneinigkeit innerhalb des Teams.</li><li>Den Ton und die Energie vorgeben</li><li>Teamdynamik managen</li><li>Die Konzentration unter Druck bewahren</li></ul><p><strong>Alle anderen:</strong></p><ul><li>Teilen Sie Ihre Sichtweise</li><li>Unterstützen Sie die getroffene Entscheidung.</li><li>Helfen Sie mit, die Teamenergie aufrechtzuerhalten.</li><li>Übernehmen Sie Verantwortung für Ihre Rolle</li></ul><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Großartige Teams sprechen miteinander, nicht übereinander. Sie kommunizieren ehrlich, respektvoll und mit dem gemeinsamen Ziel, erfolgreich zu sein.</p></blockquote><p>Üben Sie die Kommunikation wie das Werfen. Es ist eine Fähigkeit, die sich durch Übung verbessert.</p>',68))])}]]);export{u as __pageData,d as default};
